import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const m=JSON.parse('{"title":"35、【晉】 坤下離上","description":"子夏易傳 - 35、【晉】 坤下離上","frontmatter":{"title":"35、【晉】 坤下離上","description":"子夏易傳 - 35、【晉】 坤下離上"},"headers":[],"relativePath":"classics/zixia/037.md","filePath":"classics/zixia/037.md"}'),i={name:"classics/zixia/037.md"};function r(_,p,c,o,n,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="_35、【晉】-坤下離上" tabindex="-1">35、【晉】 坤下離上 <a class="header-anchor" href="#_35、【晉】-坤下離上" aria-label="Permalink to “35、【晉】 坤下離上”">​</a></h1><p>卦辭：晉，康侯用錫馬蕃庶，晝日三接。</p><p>彖曰：晉，進也。明出地上，順而麗乎大明。柔進而上行，是以康侯用錫馬蕃庶，晝日三接也。</p><p>子夏：明出地上，聖人順民而麗於大明，光於天下，方無滯於幽也。故柔進而上行，附於大明之中，極一臣之位，任為治之主，故謂為康侯錫以多馬，晝日之間而三接也。</p><p>象曰：明出地上，晉。君子以自昭明徳。</p><p>子夏：明出地上，大明之道，可進之時也。君子著其明徳，求上知之。</p><p>初六，晉如，摧如。貞吉。罔孚，裕無咎。</p><p>象曰：晉如，摧如，獨行正也。裕無咎，未受命也。</p><p>子夏：有應於上，可以進也。應近於五，未獲於情，慮其得之薄，故摧如。不進，以柔守下也。復以自知，正之吉也。未為上信，未受上命，故修徳自退，寛以居之，終無咎矣。</p><p>六二，晉如，愁如，貞吉。受茲介福，於其王母。</p><p>象曰：受茲介福，以中正也。</p><p>子夏：得位而進，無應而愁如也。夫以謹順中正，憂勤其進，非唯獲吉，抑受其福也。五以陰而降徳也。茍能立身行道，當時大明，何必待於應乎。王母，陰尊而幽逺者，猶知福之況其明王乎。</p><p>六三，眾允悔亡。</p><p>象曰：眾允之志，上行也。</p><p>子夏：處上又進悔之道也。眾允志合，故進不非，故悔亡也。</p><p>九四，晉如，鼫鼠貞厲。</p><p>象曰：鼫鼠貞厲，位不當也。</p><p>子夏：上奉於五，下據其民，剛強處卑，進不當位，其竊位也。如大鼠焉，貪而無禮，不能終矣。以之為重危之道也。</p><p>六五，悔亡，失得勿恤，往吉，無不利。</p><p>象曰：失得勿恤，往有慶也。</p><p>子夏：臣當君任，正之道也。以明盛而進弼成王化而為治主也。夫以明正為治者，則天下各當其才矣，何恤乎失得哉。以斯而往，吉其冝也。故無不利矣。</p><p>上九，晉其角，維用伐邑，厲吉無咎，貞吝。</p><p>象曰：維用伐邑，道未光也。</p><p>子夏：以柔徳治者，不能威肅天下也。故其終多用師焉。進過於禮，故曰角。進極於終，民或叛也。明正久著，人多恊焉，猶用伐邑，雖危吉也。則咎自免矣。治物不以徳，以之為政，可惜之也。</p>',24)])])}const f=a(i,[["render",r]]);export{m as __pageData,f as default};
